package kr.co.farmerflood.trigger.web;

import java.net.URLEncoder;import java.nio.charset.StandardCharsets;
import kr.co.farmerflood.trigger.service.*;
import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;import reactor.core.scheduler.Schedulers;

@RestController
public class FarmMapController {
    private final FarmMapService farms;private final ChungbukRegionService regions;
    public FarmMapController(FarmMapService farms,ChungbukRegionService regions){this.farms=farms;this.regions=regions;}
    @GetMapping(value="/api/mobile/farm-map/parcels",produces=MediaType.APPLICATION_JSON_VALUE)
    public Mono<String> parcels(@RequestParam String district,@RequestParam String locality,@RequestParam double minLon,@RequestParam double minLat,@RequestParam double maxLon,@RequestParam double maxLat){return Mono.fromCallable(()->farms.parcels(district,locality,minLon,minLat,maxLon,maxLat)).subscribeOn(Schedulers.boundedElastic());}
    @GetMapping(value="/mobile/farm-map",produces=MediaType.TEXT_HTML_VALUE)
    public String map(@RequestParam String district,@RequestParam String locality){regions.validate(district,locality);var center=regions.point(district,locality);String d=js(district),l=js(locality);return """
      <!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
      <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
      <style>*{box-sizing:border-box}html,body,#map{height:100%%;margin:0;font-family:system-ui,sans-serif}#map{background:#e9f1ec}.guide{position:absolute;z-index:900;top:14px;left:14px;right:14px;background:#143d2dcc;color:white;padding:13px 16px;border-radius:14px;font-weight:700;box-shadow:0 5px 18px #0003}.list-button{position:absolute;z-index:950;top:78px;right:14px;border:0;border-radius:999px;padding:12px 15px;background:#176b43;color:white;font-weight:800;box-shadow:0 5px 18px #0003}.sheet{display:none;position:absolute;z-index:1000;left:14px;right:14px;bottom:16px;background:white;border-radius:18px;padding:16px;box-shadow:0 10px 35px #0005}.sheet.show{display:block}.meta{color:#66756e;font-size:13px;margin:5px 0 12px}.confirm{width:100%%;border:0;border-radius:12px;padding:14px;background:#176b43;color:white;font-size:16px;font-weight:800}.empty{position:absolute;z-index:950;inset:45%% 22px auto;background:white;padding:18px;border-radius:14px;text-align:center;color:#66756e}.modal{display:none;position:absolute;z-index:1200;inset:0;background:#10201999;padding:72px 14px 16px}.modal.show{display:block}.list-panel{background:white;border-radius:20px;padding:17px;max-height:100%%;overflow:auto;box-shadow:0 12px 40px #0005}.list-head{display:flex;justify-content:space-between;align-items:center}.close{border:0;background:#edf3ef;border-radius:10px;padding:9px 12px}.parcel-row{display:flex;gap:10px;align-items:center;padding:12px 2px;border-bottom:1px solid #e4ebe7}.parcel-copy{flex:1}.parcel-copy small{display:block;color:#66756e;margin-top:3px}.remove{border:0;background:#fff0f0;color:#a33;border-radius:9px;padding:8px}.list-empty{text-align:center;color:#66756e;padding:28px 5px}.leaflet-interactive{transition:fill-opacity .15s}</style></head>
      <body><div id="map"></div><div class="guide">%s %s · 누르면 선택, 다시 누르면 해제됩니다</div><button id="listButton" class="list-button" onclick="openList()">선택 목록 0</button><div id="empty" class="empty" style="display:none">이 지역의 팜맵 데이터가 아직 적재되지 않았습니다.</div><div id="sheet" class="sheet"><b id="title"></b><div id="meta" class="meta"></div><button id="completeButton" class="confirm" onclick="completeSignup()">농경지 등록 완료</button></div><div id="listModal" class="modal"><div class="list-panel"><div class="list-head"><b>선택한 농경지</b><button class="close" onclick="closeList()">지도 보기</button></div><div id="parcelList"></div></div></div>
      <script>const district='%s',locality='%s';let layerGroup=L.layerGroup();const selected=new Map(),visibleLayers=new Map();const map=L.map('map',{zoomControl:false}).setView([%f,%f],14);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);layerGroup.addTo(map);
      function style(){return{color:'#218c5b',weight:1.5,fillColor:'#6ed39d',fillOpacity:.28}}function selectedStyle(){return{color:'#ff8a00',weight:4,fillColor:'#ffc46b',fillOpacity:.55}}function load(){const b=map.getBounds(),u=`/api/mobile/farm-map/parcels?district=${encodeURIComponent(district)}&locality=${encodeURIComponent(locality)}&minLon=${b.getWest()}&minLat=${b.getSouth()}&maxLon=${b.getEast()}&maxLat=${b.getNorth()}`;fetch(u).then(r=>r.json()).then(g=>{layerGroup.clearLayers();visibleLayers.clear();document.getElementById('empty').style.display=g.features.length?'none':'block';L.geoJSON(g,{style:f=>selected.has(f.properties.id)?selectedStyle():style(),onEachFeature:(f,ly)=>{visibleLayers.set(f.properties.id,ly);ly.on('click',()=>toggle(f,ly))}}).addTo(layerGroup)})}function toggle(f,ly){const id=f.properties.id;if(selected.has(id)){selected.delete(id);ly.setStyle(style())}else{selected.set(id,f);ly.setStyle(selectedStyle())}updateSelection(f)}function updateSelection(f){const count=selected.size;document.getElementById('listButton').textContent='선택 목록 '+count;if(count){document.getElementById('title').textContent=f.properties.crop_type+' · '+Math.round(f.properties.area_sqm||0).toLocaleString()+'㎡';document.getElementById('meta').textContent=(selected.has(f.properties.id)?'선택됨':'선택 해제됨')+' · '+f.properties.address+' · PNU '+(f.properties.pnu||'미제공');document.getElementById('completeButton').textContent='농경지 '+count+'개 등록 완료';document.getElementById('sheet').classList.add('show')}else document.getElementById('sheet').classList.remove('show')}function openList(){renderList();document.getElementById('listModal').classList.add('show')}function closeList(){document.getElementById('listModal').classList.remove('show')}function removeParcel(id){selected.delete(id);const ly=visibleLayers.get(id);if(ly)ly.setStyle(style());renderList();document.getElementById('listButton').textContent='선택 목록 '+selected.size;if(!selected.size)document.getElementById('sheet').classList.remove('show');else document.getElementById('completeButton').textContent='농경지 '+selected.size+'개 등록 완료'}function esc(v){const x=document.createElement('span');x.textContent=v||'';return x.innerHTML}function renderList(){const box=document.getElementById('parcelList'),items=[...selected.values()];box.innerHTML=items.length?items.map(f=>`<div class="parcel-row"><div class="parcel-copy"><b>${esc(f.properties.crop_type)} · ${Math.round(f.properties.area_sqm||0).toLocaleString()}㎡</b><small>${esc(f.properties.address)} · PNU ${esc(f.properties.pnu||'미제공')}</small></div><button class="remove" onclick="removeParcel('${f.properties.id}')">삭제</button></div>`).join(''):'<div class="list-empty">아직 선택한 농경지가 없습니다.</div>'}function completeSignup(){const ids=[...selected.keys()];if(!ids.length)return;const bridge=window.AndroidFarmMap;if(bridge&&typeof bridge.onParcelsSelected==='function')bridge.onParcelsSelected(JSON.stringify(ids));else alert('앱 연결을 확인할 수 없습니다. 지도를 다시 열어주세요.')}map.on('moveend',()=>{clearTimeout(window.loadTimer);window.loadTimer=setTimeout(load,250)});load();</script></body></html>
      """.formatted(district,locality,d,l,center.latitude(),center.longitude());}
    private String js(String value){return value.replace("\\","\\\\").replace("'","\\'");}
}
